INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b458c5e2-45d4-5f51-900c-7693c5cc1d15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', $$Which layer of the OSI model is primarily concerned with MAC addresses?$$::text, $$[{"id": "A", "text": "Layer 1", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": true}, {"id": "C", "text": "Layer 3", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]$$::jsonb, $$MAC addresses are Layer 2 (Data Link) identifiers used for local network delivery.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.1 Switching Concepts$$::text, 20.0, '7ad3317640949a35', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77274ce3-0b7e-5791-aab7-ea44bf4a5755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$What happens when a switch receives a unicast frame and the destination MAC is unknown?$$::text, $$[{"id": "A", "text": "Drops the frame", "is_correct": false}, {"id": "B", "text": "Forwards it out all ports except the source", "is_correct": true}, {"id": "C", "text": "Sends it to the default gateway", "is_correct": false}, {"id": "D", "text": "Buffers it indefinitely", "is_correct": false}]$$::jsonb, $$Unknown unicast frames are flooded out all ports in the same VLAN except the ingress port.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.1 Switching Concepts$$::text, 20.0, 'a0876620d1884249', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22306024-bef3-5641-a73c-b2062e031620', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', $$Which command creates VLAN 100 on a Cisco switch?$$::text, $$[{"id": "A", "text": "vlan database 100", "is_correct": false}, {"id": "B", "text": "vlan 100", "is_correct": true}, {"id": "C", "text": "create vlan 100", "is_correct": false}, {"id": "D", "text": "switchport vlan 100", "is_correct": false}]$$::jsonb, $$In global configuration mode, 'vlan 100' creates VLAN 100 on most Cisco switches.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.2 VLANs$$::text, 20.0, 'b39c64f26f767212', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5cc1dfc-085b-57e6-a774-1bfe564093d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'remember', $$Which switch port mode actively attempts to negotiate a trunk using DTP?$$::text, $$[{"id": "A", "text": "access", "is_correct": false}, {"id": "B", "text": "trunk", "is_correct": false}, {"id": "C", "text": "dynamic desirable", "is_correct": true}, {"id": "D", "text": "dynamic auto", "is_correct": false}]$$::jsonb, $$dynamic desirable actively sends DTP frames to negotiate trunking. dynamic auto only responds.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.3 Inter-Switch Connectivity$$::text, 20.0, '6e5834a27948bc2b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5adc7145-8062-5932-a6da-9d4dad7bd717', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$Which STP enhancement immediately disables a port that receives a BPDU when enabled?$$::text, $$[{"id": "A", "text": "BPDU Filter", "is_correct": false}, {"id": "B", "text": "BPDU Guard", "is_correct": true}, {"id": "C", "text": "Root Guard", "is_correct": false}, {"id": "D", "text": "Loop Guard", "is_correct": false}]$$::jsonb, $$BPDU Guard disables a PortFast port if it receives a BPDU, protecting against accidental switch connections.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.4 STP$$::text, 20.0, '0a380e9a81100899', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92b7730f-3a4b-5cad-87ef-b7042c79cab2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', $$Which wireless frame type is used to advertise an SSID?$$::text, $$[{"id": "A", "text": "Probe request", "is_correct": false}, {"id": "B", "text": "Beacon", "is_correct": true}, {"id": "C", "text": "Authentication", "is_correct": false}, {"id": "D", "text": "Association", "is_correct": false}]$$::jsonb, $$APs send beacon frames to advertise their SSID and capabilities. Stations send probe requests.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.5 Wireless$$::text, 20.0, 'a722bf07e2f53cb4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('882ed30c-9f84-5887-b21d-ed0e78cb4ca7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'remember', $$What is the maximum data rate of 802.11ac on a single 80 MHz channel with 3x3 MIMO?$$::text, $$[{"id": "A", "text": "54 Mbps", "is_correct": false}, {"id": "B", "text": "300 Mbps", "is_correct": false}, {"id": "C", "text": "1.3 Gbps", "is_correct": true}, {"id": "D", "text": "9.6 Gbps", "is_correct": false}]$$::jsonb, $$802.11ac can reach ~1.3 Gbps with 3 spatial streams and 80 MHz channels. 802.11ax (Wi-Fi 6) reaches higher.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.5 Wireless$$::text, 20.0, 'e6d9cd621beba263', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('168a3965-5fae-5813-9508-d14370befcd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'apply', $$Which command assigns a switch port to VLAN 50 as an access port?$$::text, $$[{"id": "A", "text": "switchport mode vlan 50", "is_correct": false}, {"id": "B", "text": "switchport access vlan 50", "is_correct": true}, {"id": "C", "text": "switchport trunk vlan 50", "is_correct": false}, {"id": "D", "text": "vlan 50 interface", "is_correct": false}]$$::jsonb, $$'switchport access vlan 50' assigns an access port to VLAN 50. The port must also be set to access mode.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.2 VLANs$$::text, 20.0, '05f894f2d7714064', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fe7d2ef-3401-5f29-b950-84b56f5bf529', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', $$Which routing protocol uses the Dijkstra SPF algorithm?$$::text, $$[{"id": "A", "text": "RIP", "is_correct": false}, {"id": "B", "text": "EIGRP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]$$::jsonb, $$OSPF uses Dijkstra's SPF algorithm to compute shortest paths from the LSDB.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.2 OSPF$$::text, 25.0, '396457a0b194fab9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd5b370f-835d-55cd-95e1-a0b3a1e97faa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', $$What is the default administrative distance of a directly connected route?$$::text, $$[{"id": "A", "text": "0", "is_correct": true}, {"id": "B", "text": "1", "is_correct": false}, {"id": "C", "text": "5", "is_correct": false}, {"id": "D", "text": "20", "is_correct": false}]$$::jsonb, $$Directly connected routes have an AD of 0, static routes 1, eBGP 20, EIGRP internal 90.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.1 Routing Fundamentals$$::text, 25.0, 'd8dacf7882d6a3ec', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c7edb76-fd6f-524d-9eda-0752ceab9340', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'apply', $$Which command displays the IPv6 routing table?$$::text, $$[{"id": "A", "text": "show ip route", "is_correct": false}, {"id": "B", "text": "show ipv6 route", "is_correct": true}, {"id": "C", "text": "show route ipv6", "is_correct": false}, {"id": "D", "text": "show ip route v6", "is_correct": false}]$$::jsonb, $$'show ipv6 route' displays the IPv6 routing table on Cisco IOS.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.1 Routing Fundamentals$$::text, 25.0, '7c1731570ed891c6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1662959-2293-54f0-bbf2-17d7e5a5138b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', $$Which BGP path attribute is locally significant to a router and not advertised to peers?$$::text, $$[{"id": "A", "text": "AS_Path", "is_correct": false}, {"id": "B", "text": "Local Preference", "is_correct": false}, {"id": "C", "text": "Weight", "is_correct": true}, {"id": "D", "text": "MED", "is_correct": false}]$$::jsonb, $$Weight is Cisco-proprietary, local to a router, and not advertised to BGP peers. Local Preference is advertised to iBGP peers.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.4 BGP$$::text, 25.0, 'f45cb83bd7a5bdcc', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f27b4b-e4e3-5fa9-9cb8-1ed77086b2df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', $$Which OSPF area type does not accept external (Type 5) LSAs?$$::text, $$[{"id": "A", "text": "Standard area", "is_correct": false}, {"id": "B", "text": "Stub area", "is_correct": true}, {"id": "C", "text": "Backbone area", "is_correct": false}, {"id": "D", "text": "Totally NSSA", "is_correct": false}]$$::jsonb, $$Stub areas block Type 5 external LSAs and use a default route. Totally stubby areas also block Type 3 summary LSAs.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.2 OSPF$$::text, 25.0, 'e8b8f68b943a3117', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5d3494f-b07f-5507-82b1-1a369e74e378', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$What is the purpose of a summary route?$$::text, $$[{"id": "A", "text": "To increase routing table size", "is_correct": false}, {"id": "B", "text": "To reduce routing table size", "is_correct": true}, {"id": "C", "text": "To disable routing updates", "is_correct": false}, {"id": "D", "text": "To encrypt routing traffic", "is_correct": false}]$$::jsonb, $$Route summarization aggregates multiple routes into a single advertisement, reducing routing table size and update traffic.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.1 Routing Fundamentals$$::text, 25.0, '9def3eb382df5786', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6901277-6e02-5526-b69d-049807219e41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', $$Which AAA protocol encrypts the entire communication between client and server?$$::text, $$[{"id": "A", "text": "RADIUS", "is_correct": false}, {"id": "B", "text": "TACACS+", "is_correct": true}, {"id": "C", "text": "LDAP", "is_correct": false}, {"id": "D", "text": "Kerberos", "is_correct": false}]$$::jsonb, $$TACACS+ encrypts the entire AAA payload. RADIUS encrypts only the password, and LDAP/Kerberos serve different purposes.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.2 Access Control$$::text, 15.0, 'd82758b4af7c119b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d2559a7-397b-513e-89a7-0a0c68415618', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', $$Which feature prevents a DHCP starvation attack by limiting DHCP replies to trusted ports?$$::text, $$[{"id": "A", "text": "DAI", "is_correct": false}, {"id": "B", "text": "DHCP snooping", "is_correct": true}, {"id": "C", "text": "Port security", "is_correct": false}, {"id": "D", "text": "IP Source Guard", "is_correct": false}]$$::jsonb, $$DHCP snooping marks ports as trusted or untrusted and drops DHCP server replies on untrusted ports.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.2 Access Control$$::text, 15.0, '396ba01bbb746f5f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('155249a6-0fe2-550f-84ef-6e91867aa675', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', $$What does the command 'login block-for 120 attempts 3 within 60' do?$$::text, $$[{"id": "A", "text": "Blocks all logins for 120 seconds", "is_correct": false}, {"id": "B", "text": "Blocks login attempts for 120 seconds after 3 failed attempts within 60 seconds", "is_correct": true}, {"id": "C", "text": "Allows only 3 logins per minute", "is_correct": false}, {"id": "D", "text": "Disables console login", "is_correct": false}]$$::jsonb, $$Login block-for implements quiet-mode access control: after the threshold of failed attempts is reached, logins are blocked for the specified time.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.2 Access Control$$::text, 15.0, 'ef7a6d449d50fe16', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a3d550b-6f0c-58da-82fb-a54cf569b8da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$Which REST API authentication method sends a username and password Base64-encoded in the header?$$::text, $$[{"id": "A", "text": "OAuth 2.0", "is_correct": false}, {"id": "B", "text": "Basic authentication", "is_correct": true}, {"id": "C", "text": "Token-based", "is_correct": false}, {"id": "D", "text": "Digest authentication", "is_correct": false}]$$::jsonb, $$Basic authentication encodes the username:password string in Base64 and sends it in the Authorization header.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.2 APIs$$::text, 10.0, '0e26f118d36719d4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4985dbea-91f8-5647-85b4-4b6b2d281974', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', $$Which data serialization format is commonly used by REST APIs and resembles JavaScript object notation?$$::text, $$[{"id": "A", "text": "XML", "is_correct": false}, {"id": "B", "text": "YAML", "is_correct": false}, {"id": "C", "text": "JSON", "is_correct": true}, {"id": "D", "text": "HTML", "is_correct": false}]$$::jsonb, $$JSON (JavaScript Object Notation) is lightweight, text-based, and the most common format for REST API payloads.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.2 APIs$$::text, 10.0, 'd672510f0975c9a6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('980ead8a-c4bc-55f2-a1d2-0cf5e2aa7626', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$Which component of Cisco DNA Center provides predictive analytics and baselining?$$::text, $$[{"id": "A", "text": "Automation", "is_correct": false}, {"id": "B", "text": "Assurance", "is_correct": true}, {"id": "C", "text": "Fabric", "is_correct": false}, {"id": "D", "text": "Identity Services", "is_correct": false}]$$::jsonb, $$Cisco DNA Center Assurance provides monitoring, baselining, and predictive analytics using telemetry.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.1 Automation$$::text, 10.0, 'a5d5dfd6b41d7092', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a387a7fd-c45d-5583-83db-86588fef2832', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', $$What is the function of Terraform in network automation?$$::text, $$[{"id": "A", "text": "Monitor device health", "is_correct": false}, {"id": "B", "text": "Provision infrastructure using declarative code", "is_correct": true}, {"id": "C", "text": "Collect syslog messages", "is_correct": false}, {"id": "D", "text": "Authenticate API users", "is_correct": false}]$$::jsonb, $$Terraform is an IaC tool that provisions and manages infrastructure using declarative configuration files.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.1 Automation$$::text, 10.0, 'aadf449ad626e7a6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca5dca2c-a09f-54f2-959a-b90d16842a1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', $$Which type of machine learning generates new content such as text or code?$$::text, $$[{"id": "A", "text": "Supervised learning", "is_correct": false}, {"id": "B", "text": "Unsupervised learning", "is_correct": false}, {"id": "C", "text": "Reinforcement learning", "is_correct": false}, {"id": "D", "text": "Generative AI", "is_correct": true}]$$::jsonb, $$Generative AI models create new content. Supervised, unsupervised, and reinforcement learning focus on prediction, grouping, and decision-making.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.3 AI/ML$$::text, 10.0, '273a5c077b3e085c', true) ON CONFLICT (id) DO NOTHING;
